# KIRO2 deploy_all.ps1 v2.9 — DB schema uyumlu SQL
param(
    [string]$Root      = "C:\Users\husey\kiro2",
    [string]$Db        = "kiro2",
    [string]$PgPort    = "5434",
    [string]$PgUser    = "postgres",
    [string]$PgPass    = "changeme_strong_password_here",
    [string]$PgHost    = "localhost",
    [switch]$SkipTests,
    [switch]$SkipMigrations
)
$ErrorActionPreference = "Continue"
function OK  { Write-Host "  [OK] $args" -ForegroundColor Green }
function ERR { Write-Host "  [!!] $args" -ForegroundColor Red }
function INF { Write-Host "  [--] $args" -ForegroundColor Cyan }
function HDR { Write-Host "`n=== $args ===" -ForegroundColor Magenta }
function Write-Utf8 {
    param([string]$FilePath, [string]$Content)
    $dir = Split-Path $FilePath -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
    if (Test-Path $FilePath) { Copy-Item $FilePath "$FilePath.bak" -Force -EA SilentlyContinue }
    [IO.File]::WriteAllText($FilePath, $Content, (New-Object System.Text.UTF8Encoding($false)))
}
function Decode-B64 { param([string]$B64)
    [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($B64))
}
Write-Host "KIRO2 DEPLOY v2.9`nRoot: $Root" -ForegroundColor Magenta
if (-not (Test-Path $Root)) { ERR "Dizin yok: $Root"; exit 1 }

HDR '1. DOSYALAR (30 dosya)'
Write-Utf8 "$Root\backend\main.py" (Decode-B64 '')
OK 'main.py'
Write-Utf8 "$Root\backend\app\core\deps.py" (Decode-B64 '')
OK 'deps.py'
Write-Utf8 "$Root\backend\app\services\irt_engine.py" (Decode-B64 '')
OK 'irt_engine.py'
Write-Utf8 "$Root\backend\app\services\cat_session.py" (Decode-B64 '')
OK 'cat_session.py'
Write-Utf8 "$Root\backend\app\services\irt_calibrator.py" (Decode-B64 '')
OK 'irt_calibrator.py'
Write-Utf8 "$Root\backend\app\services\fsrs_engine.py" (Decode-B64 '')
OK 'fsrs_engine.py'
Write-Utf8 "$Root\backend\app\services\fsrs_service.py" (Decode-B64 '')
OK 'fsrs_service.py'
Write-Utf8 "$Root\backend\app\services\dag_engine.py" (Decode-B64 '')
OK 'dag_engine.py'
Write-Utf8 "$Root\backend\app\services\dag_service.py" (Decode-B64 '')
OK 'dag_service.py'
Write-Utf8 "$Root\backend\app\services\placement_service.py" (Decode-B64 '')
OK 'placement_service.py'
Write-Utf8 "$Root\backend\app\services\yks_estimator.py" (Decode-B64 '')
OK 'yks_estimator.py'
Write-Utf8 "$Root\backend\app\api\cat.py" (Decode-B64 '')
OK 'cat.py'
Write-Utf8 "$Root\backend\app\api\fsrs.py" (Decode-B64 '')
OK 'fsrs.py'
Write-Utf8 "$Root\backend\app\api\dag.py" (Decode-B64 '')
OK 'dag.py'
Write-Utf8 "$Root\backend\app\api\placement.py" (Decode-B64 '')
OK 'placement.py'
Write-Utf8 "$Root\backend\app\api\estimator.py" (Decode-B64 '')
OK 'estimator.py'
Write-Utf8 "$Root\backend\app\schemas\cat_schemas.py" (Decode-B64 '')
OK 'cat_schemas.py'
Write-Utf8 "$Root\backend\app\schemas\fsrs_schemas.py" (Decode-B64 '')
OK 'fsrs_schemas.py'
Write-Utf8 "$Root\backend\app\tasks\calibration_task.py" (Decode-B64 '')
OK 'calibration_task.py'
Write-Utf8 "$Root\alembic\versions\001_cat_sessions.sql" (Decode-B64 '')
OK '001_cat_sessions.sql'
Write-Utf8 "$Root\alembic\versions\002_irt_calibration.sql" (Decode-B64 '')
OK '002_irt_calibration.sql'
Write-Utf8 "$Root\alembic\versions\003_fsrs.sql" (Decode-B64 '')
OK '003_fsrs.sql'
Write-Utf8 "$Root\alembic\versions\004_dag.sql" (Decode-B64 '')
OK '004_dag.sql'
Write-Utf8 "$Root\backend\tests\test_cat.py" (Decode-B64 '')
OK 'test_cat.py'
Write-Utf8 "$Root\backend\tests\test_irt_calibration.py" (Decode-B64 '')
OK 'test_irt_calibration.py'
Write-Utf8 "$Root\backend\tests\test_fsrs.py" (Decode-B64 '')
OK 'test_fsrs.py'
Write-Utf8 "$Root\backend\tests\test_dag.py" (Decode-B64 '')
OK 'test_dag.py'
Write-Utf8 "$Root\backend\tests\test_placement.py" (Decode-B64 '')
OK 'test_placement.py'
Write-Utf8 "$Root\backend\tests\test_estimator.py" (Decode-B64 '')
OK 'test_estimator.py'
Write-Utf8 "$Root\backend\tests\conftest.py" (Decode-B64 '')
OK 'conftest.py'

@("backend\app","backend\app\core","backend\app\services","backend\app\api",
  "backend\app\schemas","backend\app\tasks","backend\tests") | ForEach-Object {
    $init = "$Root\$_\__init__.py"
    if (-not (Test-Path $init)) { Write-Utf8 $init ""; OK "  __init__.py: $_" }
}


HDR '2. PIP'
Push-Location "$Root\backend"
pip install scipy "redis[asyncio]" "celery[redis]" numpy --quiet 2>&1 | Select-Object -Last 1
OK "pip tamamlandi"
Pop-Location


HDR '3. MIGRATIONS'
$psql = $null
foreach ($p in @("psql","C:\Program Files\PostgreSQL\18\bin\psql.exe","C:\Program Files\PostgreSQL\17\bin\psql.exe","C:\Program Files\PostgreSQL\16\bin\psql.exe","C:\Program Files\PostgreSQL\15\bin\psql.exe")) {
    if (Get-Command $p -EA SilentlyContinue) { $psql = $p; break }
}
if ($psql -and -not $SkipMigrations) {
    $env:PGPASSWORD = $PgPass
    @("001_cat_sessions","002_irt_calibration","003_fsrs","004_dag") | ForEach-Object {
        $sql = "$Root\alembic\versions\$_.sql"
        if (Test-Path $sql) {
            $out = & $psql -h $PgHost -p $PgPort -U $PgUser -d $Db -f $sql 2>&1
            $err = $out | Where-Object { $_ -match "ERROR" -and $_ -notmatch "already exists" }
            if ($err) { ERR "$_.sql: $($err[0])" } else { OK "$_.sql" }
        } else { ERR "SQL yok: $sql" }
    }
    Remove-Item Env:\PGPASSWORD -EA SilentlyContinue
} elseif ($SkipMigrations) {
    INF "-SkipMigrations"
} else {
    ERR "psql bulunamadi. PATH'e ekle veya tam yol ver."
}


HDR '4. TESTLER'
if (-not $SkipTests) {
    Push-Location "$Root\backend"
    $t = @(
        @{F="tests\test_cat.py";             N="CAT";       E=26},
        @{F="tests\test_irt_calibration.py"; N="IRT";       E=32},
        @{F="tests\test_fsrs.py";            N="FSRS";      E=44},
        @{F="tests\test_dag.py";             N="DAG";       E=39},
        @{F="tests\test_placement.py";       N="Placement"; E=26},
        @{F="tests\test_estimator.py";       N="Estimator"; E=35}
    )
    $total = 0; $fails = 0
    foreach ($tt in $t) {
        if (-not (Test-Path $tt.F)) { ERR "$($tt.N): yok"; $fails++; continue }
        $r = python -m pytest $tt.F -q --tb=short 2>&1
        $last = ($r | Select-Object -Last 1)
        if ($last -match "(\d+) passed") {
            $p = [int]$Matches[1]; $total += $p
            if ($p -ge $tt.E) { OK "$($tt.N): $p/$($tt.E)" } else { ERR "$($tt.N): $p/$($tt.E)"; $fails++ }
        } else {
            ERR "$($tt.N): BASARISIZ"
            $r | Select-Object -Last 4 | ForEach-Object { INF $_ }
            $fails++
        }
    }
    Pop-Location
    if ($fails -eq 0) { Write-Host "  $total/202 TEST GECTI" -ForegroundColor Green }
    else { Write-Host "  $total gecti, $fails basarisiz" -ForegroundColor Yellow }
} else { INF "-SkipTests" }


HDR '5. BACKEND'
INF "Backend'i yeniden baslat:"
INF "  cd $Root\backend && uvicorn main:app --reload --port 8000"
try {
    $r = Invoke-WebRequest "http://localhost:8000/health" -UseBasicParsing -TimeoutSec 3 2>$null
    if ($r.StatusCode -eq 200) {
        $spec = (Invoke-WebRequest "http://localhost:8000/openapi.json" -UseBasicParsing 2>$null).Content | ConvertFrom-Json
        @("/api/v1/cat","/api/v1/fsrs","/api/v1/dag","/api/v1/placement","/api/v1/estimate") | ForEach-Object {
            $pattern = $_
            $n = ($spec.paths.PSObject.Properties.Name | Where-Object { $_ -like "*$pattern*" }).Count
            if ($n -gt 0) { OK "$pattern ($n endpoint)" } else { ERR "$pattern eksik — backend'i yeniden baslat" }
        }
    }
} catch { INF "Backend kapali." }
Write-Host "`nDEPLOY v2.9 TAMAMLANDI" -ForegroundColor Cyan
